const t = $('When Role Requested').first().json;
return [{ json: {
  clientName: t.clientName,
  playbookFile: t.playbookFile,
  roleTag: t.roleTag,
  targetIP: t.targetIP,
  timeoutSeconds: Number(t.timeoutSeconds) || 600,
  runId: t.runId,
  maxAttempts: Number(t.maxAttempts) || 5
} }];

const NEWLINE = String.fromCharCode(10);
const r = $json;
const raw = String(r.stdout || '');
const idx = raw.lastIndexOf('EXIT_CODE:');
let exitCode;
if (idx >= 0) { exitCode = parseInt(raw.slice(idx + 10).trim(), 10); } else { exitCode = (r.code === 0 ? 0 : 1); }
if (isNaN(exitCode)) { exitCode = 1; }
const success = exitCode === 0;
let attempt = 1;
try { const inc = $('Increment Attempt').item.json.attempt; if (inc) { attempt = Number(inc); } } catch (e) {}
const allLines = raw.split(NEWLINE);
const tail = allLines.slice(-40).map(function (l) {
  const low = String(l).toLowerCase();
  if (low.indexOf('password') >= 0 || low.indexOf('secret') >= 0 || low.indexOf('token') >= 0 || low.indexOf('private key') >= 0 || low.indexOf('vault') >= 0 || low.indexOf('-----begin') >= 0) { return '[line redacted for secrets]'; }
  return l;
});
const errorExcerpt = tail.join(NEWLINE).slice(-3500);
const recapIdx = raw.lastIndexOf('PLAY RECAP');
const recap = recapIdx >= 0 ? raw.slice(recapIdx).slice(0, 800) : '';
const t = $('When Role Requested').first().json;
return [{ json: {
  clientName: t.clientName,
  roleTag: t.roleTag,
  playbookFile: t.playbookFile,
  runId: t.runId,
  maxAttempts: Number(t.maxAttempts) || 5,
  exitCode: exitCode,
  success: success,
  attempt: attempt,
  errorExcerpt: errorExcerpt,
  recap: recap
} }];

